import type { TopicalExam } from './types'

function q(id: number, question: string, options: string[], correctAnswer: number, explanation: string) {
  return { id, question, options, correctAnswer, explanation }
}

export const TOPICAL_ENGLISH_LANG: TopicalExam = {
  label: 'AP English Language and Composition',
  slug: 'ap-english-language-and-composition',
  units: [
    {
      unitNumber: 1,
      title: 'Rhetorical Situation',
      easy: [
        q(1, 'The "rhetorical situation" refers to:', ['The grammatical structure of a written argument', 'The context in which communication occurs, including the speaker, audience, subject, purpose, and occasion', 'The use of figurative language in persuasive writing', 'The logical structure of a formal debate'], 1, 'The rhetorical situation encompasses all the contextual factors surrounding communication: who is speaking/writing (speaker), to whom (audience), about what (subject), why (purpose), and under what circumstances (occasion/context). Understanding these elements is essential for effective rhetorical analysis.'),
        q(2, 'An author\'s "purpose" in writing refers to:', ['The length and format of the text', 'The reason the author is writing—what they hope to achieve with the audience', 'The topic or subject of the text', 'The number of sources cited in the text'], 1, 'Purpose is the author\'s reason for writing—what they intend to accomplish. Common purposes include persuading, informing, entertaining, explaining, or calling the audience to action. Purpose shapes every choice the writer makes, from tone to evidence to structure.'),
        q(3, 'Ethos, as a rhetorical appeal, refers to:', ['An appeal to the audience\'s emotions', 'An appeal based on the speaker\'s credibility, character, and trustworthiness', 'An appeal to logic and evidence', 'An appeal to the audience\'s sense of morality'], 1, 'Ethos is the rhetorical appeal to credibility and character. Writers establish ethos through demonstrating expertise, citing credible sources, using appropriate tone, acknowledging counterarguments, and presenting themselves as trustworthy and knowledgeable on the subject.'),
        q(4, 'Which of the following best describes the concept of "audience" in rhetoric?', ['Anyone who might happen to read a text', 'The intended recipients of a message whose characteristics and expectations shape the writer\'s choices', 'Only the teacher grading a student\'s essay', 'The author\'s peers in their professional field'], 1, 'The audience is the intended recipient(s) of the communication. Effective writers analyze their audience\'s knowledge, values, beliefs, expectations, and potential objections, then tailor their message—including language, evidence, tone, and structure—accordingly.'),
        q(5, 'A writer composing a eulogy at a funeral and a writer crafting a political campaign speech differ primarily in their:', ['Ability to write well', 'Rhetorical situation—different occasions, audiences, and purposes shape different rhetorical choices', 'Use of the English language', 'Knowledge of grammar and mechanics'], 1, 'These writers face different rhetorical situations: different occasions (funeral vs. campaign), purposes (honoring/comforting vs. persuading), and audience expectations (mourners seeking solace vs. voters evaluating candidates). These contextual differences necessitate fundamentally different rhetorical strategies.'),
      ],
      medium: [
        q(6, 'A senator writing an op-ed about healthcare reform for a national newspaper makes different rhetorical choices than when writing the same policy in legislative language. Which element of the rhetorical situation best explains this difference?', ['The subject changes between the two documents.', 'The audience changes—general newspaper readers versus legislators—requiring different levels of technical language, different appeals, and different levels of assumed knowledge.', 'The senator\'s credibility changes between contexts.', 'The purpose remains identical in both situations.'], 1, 'The audience is the key variable. Newspaper readers need accessible language, emotional appeals, real-world examples, and simplified policy explanations. Legislators expect precise legal language, technical details, procedural references, and policy specifics. The subject is the same, but audience expectations drive different rhetorical approaches.'),
        q(7, 'An author establishes credibility early in an essay by acknowledging the complexity of the issue and noting valid points made by opponents. This strategy primarily builds:', ['Pathos by showing emotional sensitivity', 'Ethos by demonstrating fairness, intellectual honesty, and thorough understanding of the topic', 'Logos by presenting statistical evidence', 'Kairos by addressing the timeliness of the issue'], 1, 'Acknowledging opposing viewpoints (concession) builds ethos by demonstrating that the author is fair-minded, intellectually honest, and knowledgeable about the full scope of the debate. This makes the audience more likely to trust the author\'s judgment when they present their own position.'),
        q(8, 'The concept of "kairos" in rhetoric refers to:', ['The logical structure of an argument', 'The opportune moment or timeliness of an argument—how the specific historical, cultural, or situational context makes the message particularly relevant', 'The emotional impact of a speech', 'The author\'s biographical background'], 1, 'Kairos is the Greek rhetorical concept of the right or opportune moment. It considers how timing and context affect the persuasiveness of an argument. A speech about disaster preparedness is more kairotic immediately after a natural disaster. Writers who recognize and leverage kairos make their arguments more urgent and relevant.'),
        q(9, 'When analyzing a rhetorical text, identifying the "exigence" means identifying:', ['The author\'s educational background', 'The issue, problem, or situation that prompted the author to write or speak—the urgency or need that the text addresses', 'The publication date of the text', 'The text\'s genre classification'], 1, 'Exigence is the pressing issue, event, or situation that compels the author to communicate. It is the "spark" that generates the need for discourse. Understanding exigence helps explain why a text exists, what problem it responds to, and what the author feels must be addressed.'),
        q(10, 'A writer addressing a hostile audience (one that disagrees with their position) would most likely benefit from which opening strategy?', ['Immediately stating their thesis in the strongest possible terms', 'Establishing common ground with the audience before introducing the controversial claim', 'Using highly technical jargon to demonstrate expertise', 'Ignoring the audience\'s perspective entirely'], 1, 'When facing a hostile audience, establishing common ground (shared values, concerns, or goals) before introducing a controversial thesis creates a foundation of goodwill and reduces defensiveness. This Rogerian approach builds ethos and makes the audience more receptive to hearing the writer\'s position.'),
      ],
      hard: [
        q(11, 'A political commentator publishes an article arguing for education reform in both an academic journal and a popular magazine. Beyond vocabulary differences, which deeper rhetorical adaptation reflects a sophisticated understanding of these different audiences?', ['Using the same evidence in both versions', 'Adjusting the burden of proof and type of evidence: the academic version relies on peer-reviewed studies and acknowledges methodological limitations, while the magazine version uses compelling narratives, accessible statistics, and appeals to shared values about children\'s futures.', 'Making the magazine version longer and more detailed', 'Using more complex sentence structures in the magazine version'], 1, 'Sophisticated rhetorical adaptation goes beyond simplifying language—it involves fundamentally different evidence strategies, proof standards, and persuasive approaches. Academic audiences expect rigorous methodology and nuanced claims; popular audiences respond to narrative, accessible data, and value-based appeals. The writer must understand what each audience considers convincing.'),
        q(12, 'A civil rights leader delivers a speech drawing on biblical allusions and the language of American founding documents. This strategy reflects an understanding of which aspect of the rhetorical situation?', ['The speaker\'s personal religious beliefs', 'The audience\'s shared cultural and political texts, using these intertextual references to create identification and frame the civil rights cause within values the audience already accepts', 'The requirement to use literary devices in speeches', 'The historical period\'s preference for religious language'], 1, 'This strategy leverages shared cultural texts (the Bible, the Declaration of Independence, the Constitution) to create identification between the speaker and audience. By framing civil rights within documents and traditions the audience already reveres, the speaker positions their cause as consistent with deeply held American and religious values, making opposition to civil rights appear inconsistent with the audience\'s own beliefs.'),
        q(13, 'An essayist argues that social media has damaged democratic discourse. In the conclusion, they directly address social media executives by name, shifting from third person to second person. This shift in rhetorical situation most effectively:', ['Weakens the argument by alienating the primary audience', 'Creates a rhetorical move called "apostrophe" that dramatizes accountability, makes the argument more urgent, and implicitly invites the broader audience to join in holding these figures responsible', 'Is a grammatical error that should be corrected', 'Has no rhetorical effect on the essay'], 1, 'This shift from third-person analysis to second-person direct address (apostrophe) transforms the essay from detached commentary to direct confrontation. It dramatizes accountability, increases urgency, and positions the broader audience as witnesses to this address, implicitly enlisting them as allies in demanding change. It\'s a deliberate rhetorical choice that reshapes the writer-audience relationship.'),
        q(14, 'A writer deliberately adopts a persona that differs from their personal views to make a satirical argument (as Jonathan Swift does in "A Modest Proposal"). The effectiveness of this rhetorical strategy depends on:', ['The audience\'s inability to detect the irony', 'The audience\'s recognition that the speaker\'s extreme position reveals, through ironic contrast, the absurdity or immorality of the actual situation being criticized', 'The writer\'s sincere belief in the persona\'s views', 'The clarity and directness of the argument'], 1, 'Satirical persona works when the audience recognizes the gap between the persona\'s stated position and the writer\'s actual intent. The persona\'s "reasonable" advocacy of something outrageous forces readers to confront the real-world problems being satirized. If the audience takes the persona at face value, the satire fails—sophistication depends on shared understanding between writer and reader.'),
        q(15, 'Two op-eds respond to the same event: one published the day after, and one published six months later. A rhetorical analyst would note that the difference in timing affects:', ['Only the factual accuracy of each piece', 'The entire rhetorical situation: the first leverages immediacy and emotional resonance (kairos) but risks incomplete information; the later piece benefits from perspective and comprehensive evidence but must overcome diminished urgency and audience attention.', 'Nothing significant—the arguments should be identical regardless of timing', 'Only the audience\'s familiarity with the event'], 1, 'Timing fundamentally shapes the rhetorical situation. The immediate response harnesses raw emotion, urgency, and public attention (strong kairos) but may lack complete information or nuanced analysis. The later response benefits from fuller evidence, historical context, and reflective analysis but must work harder to re-engage an audience whose attention has moved on. Each faces different rhetorical challenges and opportunities.'),
      ],
    },
    {
      unitNumber: 2,
      title: 'Claims and Evidence',
      easy: [
        q(16, 'A "claim" in an argument is best defined as:', ['A fact that everyone agrees upon', 'An assertion or thesis that the writer argues is true and supports with evidence', 'A question posed to the reader', 'A summary of opposing viewpoints'], 1, 'A claim is the writer\'s central assertion—the position they are arguing for. It is debatable (reasonable people could disagree), specific enough to be supported with evidence, and serves as the thesis or main point around which the argument is built.'),
        q(17, 'Which of the following is an example of a qualitative evidence source?', ['A statistical survey of 10,000 respondents', 'A personal interview with an expert providing their professional interpretation', 'A spreadsheet of economic data', 'A graph showing population growth trends'], 1, 'Qualitative evidence includes non-numerical data such as interviews, observations, personal experiences, case studies, and textual analysis. A personal interview provides insight into perspectives, experiences, and expert interpretations that quantitative data alone cannot capture.'),
        q(18, 'A "counterargument" in an essay serves which purpose?', ['To weaken the writer\'s own position', 'To acknowledge opposing viewpoints and strengthen the writer\'s argument by addressing and refuting them', 'To confuse the reader about the writer\'s position', 'To introduce a completely new topic'], 1, 'Counterarguments strengthen an essay by showing the writer has considered opposing perspectives. By acknowledging and then refuting objections, the writer demonstrates thoroughness, builds credibility (ethos), and preemptively addresses doubts the audience might have.'),
        q(19, 'The difference between a fact and an opinion is that:', ['Facts are always true and opinions are always false.', 'Facts can be verified or proven, while opinions express judgments, interpretations, or beliefs that are debatable.', 'Facts are found in textbooks and opinions are found in newspapers.', 'There is no meaningful difference.'], 1, 'Facts are objective statements that can be verified through observation, measurement, or documentation. Opinions involve subjective judgment, interpretation, or evaluation. Strong arguments use verified facts as evidence to support debatable claims (opinions/interpretations).'),
        q(20, 'An author citing a peer-reviewed scientific study to support their argument is using which type of evidence?', ['Anecdotal evidence', 'Empirical evidence from a credible, authoritative source', 'Hearsay', 'Emotional appeal'], 1, 'Peer-reviewed scientific studies represent empirical evidence from authoritative sources. The peer-review process ensures the research has been evaluated by experts, adding credibility. This type of evidence is particularly persuasive in arguments requiring factual support.'),
      ],
      medium: [
        q(21, 'A writer argues that standardized testing should be eliminated from college admissions. They support this with a single student\'s story of being rejected despite excellent grades. This evidence is limited primarily because:', ['Personal stories are never relevant in arguments.', 'A single anecdote, while vivid, cannot establish a pattern or represent the broader population\'s experience and is vulnerable to the charge that it is atypical.', 'The student was probably not qualified anyway.', 'College admissions are too complex to discuss.'], 1, 'While anecdotal evidence can be emotionally compelling and humanize an issue, a single example cannot demonstrate a widespread pattern. The anecdote might be atypical, and opponents can easily dismiss it as an outlier. Effective arguments pair anecdotes with broader data (statistics, studies, expert analysis) to establish that the individual example reflects a systemic issue.'),
        q(22, 'A writer presents evidence that crime rates have decreased in cities that increased police funding. An effective rebuttal to this argument might point out that:', ['Crime rates never decrease.', 'Correlation does not equal causation—other factors (economic improvement, demographic changes, policing strategies independent of funding) may have contributed to the decline, and the evidence doesn\'t establish that increased funding caused the decrease.', 'Police funding should always increase regardless of crime rates.', 'Crime statistics are always unreliable.'], 1, 'Pointing out that correlation does not equal causation is a fundamental analytical move. The evidence shows two things happened together (increased funding, decreased crime) but doesn\'t prove a causal link. Multiple confounding variables could explain the crime decline, and without controlling for these factors, the causal claim is unsupported.'),
        q(23, 'The distinction between a "claim of fact," a "claim of value," and a "claim of policy" is important because:', ['Only claims of fact are used in academic writing.', 'Each type of claim requires different kinds of evidence and warrants: factual claims need empirical proof, value claims need criteria for judgment, and policy claims need both evidence of a problem and a feasible solution.', 'Claims of value are always stronger than claims of fact.', 'Only claims of policy are relevant to persuasive writing.'], 1, 'Different claim types demand different argumentative strategies. Claims of fact require evidence proving something is true. Claims of value require establishing evaluative criteria and showing something meets those criteria. Claims of policy require demonstrating a problem exists (claim of fact), that it matters (claim of value), and that a workable solution exists, each demanding appropriate evidence.'),
        q(24, 'A writer uses the phrase "studies show that..." without citing specific studies, researchers, or publications. This weakens the argument because:', ['Studies are never relevant to arguments.', 'The vague attribution lacks specificity, preventing the audience from evaluating the credibility, methodology, or relevance of the evidence, and it may signal that the writer is fabricating or exaggerating support.', 'All evidence must be presented as direct quotations.', 'The audience already knows which studies the writer means.'], 1, 'Vague attributions like "studies show" or "experts agree" lack the specificity needed for credibility. Without naming researchers, publications, sample sizes, or methodologies, the audience cannot evaluate the evidence\'s quality. This weakens ethos by suggesting the writer either doesn\'t know the specific evidence or is attempting to manufacture authority for unsupported claims.'),
        q(25, 'A writer argues that renewable energy is economically beneficial by citing both the declining cost of solar panels over the past decade and the number of jobs created in the renewable energy sector. This use of multiple types of evidence strengthens the argument by:', ['Making the essay longer', 'Providing converging evidence from different angles (cost trends and employment data) that reinforces the economic claim, making it harder to dismiss and more persuasive to audiences with different priorities', 'Confusing the audience with too much information', 'Demonstrating that the writer can use Google'], 1, 'Multiple types of evidence addressing the same claim from different angles create a more robust argument. Cost data appeals to fiscal conservatives, while job creation data appeals to those prioritizing employment. If an opponent challenges one type of evidence, the other still supports the claim. This triangulation of evidence is more persuasive than relying on a single data point.'),
      ],
      hard: [
        q(26, 'A historian argues that the New Deal prolonged the Great Depression, citing economic data from 1933-1939 showing slow recovery. An opponent cites the same period\'s data showing significant GDP growth and unemployment reduction. How should a rhetorical analyst evaluate this use of competing evidence?', ['One side must be fabricating data.', 'Both sides may be accurately presenting different aspects of the same data set—selectively emphasizing metrics that support their claims—demonstrating that evidence interpretation is shaped by the analyst\'s framing, criteria for success, and underlying assumptions.', 'Economic data is inherently unreliable and should not be used as evidence.', 'The most recent interpretation is always the most accurate.'], 1, 'This illustrates how the same data can support different claims depending on which metrics are emphasized, what benchmarks are used for comparison, and what theoretical framework guides interpretation. "Slow recovery" and "significant growth" may both accurately describe different aspects of the data. Rhetorical analysis examines how writers select, frame, and interpret evidence to support their predetermined conclusions.'),
        q(27, 'A writer builds an argument entirely on expert testimony, citing six different authorities who agree with the thesis. A sophisticated critical reader should:', ['Accept the argument because expert consensus is conclusive.', 'Evaluate whether the experts are genuinely independent, representative of broader expert opinion, speaking within their areas of expertise, and whether the writer has ignored equally qualified experts who disagree.', 'Reject all expert testimony as biased.', 'Count the number of experts cited and compare to the opposition.'], 1, 'Sophisticated readers evaluate expert testimony critically: Are the experts qualified in the relevant field? Are they truly independent or connected to interested parties? Do they represent the broader expert consensus or a minority view? Has the writer cherry-picked agreeable experts while ignoring disagreeing ones? Expert authority strengthens arguments only when the expertise is relevant, independent, and representative.'),
        q(28, 'The rhetorical concept of a "warrant" (from Toulmin\'s model) is the often unstated assumption connecting evidence to a claim. In the argument "We should ban pesticide X because it has been found in drinking water," the unstated warrant is:', ['Pesticide X is used in agriculture.', 'Substances found in drinking water are potentially harmful and should be regulated to protect public health.', 'Drinking water should be free for all citizens.', 'All pesticides should be banned.'], 1, 'The warrant bridges the evidence (pesticide X found in drinking water) and the claim (ban pesticide X). The unstated assumption is that the presence of pesticides in drinking water poses a health risk that justifies regulatory action. If the audience doesn\'t share this warrant (perhaps believing trace amounts are harmless), the argument fails regardless of the evidence. Effective writers identify and, when necessary, explicitly support their warrants.'),
        q(29, 'A journalist writing about immigration uses extensive statistical data but frames each data point with emotionally charged language ("staggering numbers," "overwhelming flood," "crisis proportions"). A rhetorical analyst would identify this as:', ['Effective use of logos to present factual information', 'A rhetorical strategy that blurs the line between logos and pathos, where the selective framing and loaded language may lead readers to draw conclusions beyond what the raw data supports', 'Poor journalism that should present data without any interpretation', 'An exclusively emotional argument with no logical basis'], 1, 'This technique layers emotional framing (pathos) over statistical evidence (logos), creating an argument that appears data-driven but is significantly shaped by connotative language. Words like "staggering," "overwhelming," and "crisis" carry emotional weight that influences interpretation of the data. The data might be accurate, but the framing guides readers toward conclusions the raw numbers alone might not support—a sophisticated rhetorical move that requires critical reader awareness.'),
        q(30, 'When a writer concedes that "my opponent makes a valid point about X" but then argues "however, this concern is outweighed by Y and Z," they are employing:', ['A logical fallacy that weakens their position', 'A strategic concession-and-rebuttal pattern that strengthens credibility by demonstrating fairness while ultimately advancing their position through a comparative weighing of competing considerations', 'An admission of defeat on the overall argument', 'An irrelevant digression from the main thesis'], 1, 'The concession-and-rebuttal pattern is one of the most powerful argumentative moves. Conceding a valid opposing point builds ethos (fairness, thoroughness) and disarms opponents who expected their point to be ignored. The "however" pivot reframes the conceded point as less significant than the writer\'s own evidence, creating a hierarchy of considerations that supports the thesis. This is more persuasive than ignoring or dismissing opposing views.'),
      ],
    },
    {
      unitNumber: 3,
      title: 'Reasoning and Organization',
      easy: [
        q(31, 'Deductive reasoning moves from:', ['Specific observations to a general conclusion', 'A general principle to a specific conclusion', 'One specific example to another specific example', 'An emotional appeal to a logical conclusion'], 1, 'Deductive reasoning begins with a general principle (major premise), applies it to a specific case (minor premise), and draws a specific conclusion. If the premises are true and the logic valid, the conclusion is necessarily true. Example: All humans are mortal (general) → Socrates is human (specific) → Socrates is mortal (conclusion).'),
        q(32, 'Inductive reasoning moves from:', ['A general principle to a specific conclusion', 'Specific observations or examples to a broader generalization', 'A thesis to supporting evidence', 'An emotional appeal to a factual claim'], 1, 'Inductive reasoning draws general conclusions from specific observations, examples, or evidence. Unlike deduction, inductive conclusions are probable rather than certain. Example: Every swan I\'ve observed is white → Therefore, all swans are probably white. The strength depends on the quantity and representativeness of the observations.'),
        q(33, 'A thesis statement in an argumentative essay should:', ['Be a question that the essay explores', 'Present a clear, debatable claim that the essay will support with evidence and reasoning', 'Summarize the opposing viewpoint', 'List all the evidence the essay will use'], 1, 'An effective thesis presents a clear, specific, debatable claim—not a statement of fact or a question. It signals the writer\'s position and provides a roadmap for the argument, giving readers a preview of what the essay will prove and how.'),
        q(34, 'A "logical fallacy" is:', ['A type of evidence used in scientific arguments', 'An error in reasoning that undermines the logic of an argument', 'A rhetorical device used to strengthen an argument', 'A persuasive technique endorsed by rhetorical theorists'], 1, 'Logical fallacies are flaws in reasoning that weaken arguments. They may seem persuasive on the surface but do not actually support the conclusion. Common fallacies include ad hominem (attacking the person), straw man (misrepresenting the opponent\'s argument), false dichotomy, and hasty generalization.'),
        q(35, 'Organizing an argument by presenting the weakest points first and building toward the strongest point is called:', ['Chronological order', 'Emphatic (climactic) order', 'Spatial order', 'Random order'], 1, 'Emphatic or climactic order arranges arguments from least to most compelling. This structure builds momentum, ends with the strongest impression, and is strategically effective because audiences tend to remember the last point most vividly. It leaves readers with the writer\'s most powerful evidence and reasoning.'),
      ],
      medium: [
        q(36, 'A writer argues: "If we allow students to use AI for essays, next they\'ll use it for exams, then for dissertations, and eventually no one will learn to write at all." This is an example of which logical fallacy?', ['Ad hominem', 'Slippery slope—assuming one action will inevitably lead to a chain of extreme consequences without establishing the causal links between each step', 'Straw man', 'Appeal to authority'], 1, 'The slippery slope fallacy assumes that one event will trigger an inevitable chain of increasingly extreme consequences without providing evidence that each step necessarily follows from the previous one. The argument skips over the possibility of stopping at any point and treats a possible outcome as certain.'),
        q(37, 'A "Rogerian argument" differs from a classical argument in that a Rogerian argument:', ['Immediately states the writer\'s thesis and attacks opposing views', 'Begins by finding common ground with the opposing viewpoint, fairly represents the opposition\'s position, and seeks compromise rather than outright victory', 'Uses only emotional appeals to persuade the audience', 'Avoids stating any position at all'], 1, 'Rogerian argument (based on Carl Rogers\' communication theory) is designed for highly controversial topics where the audience is likely hostile. It begins by demonstrating understanding of the opposing position, identifies shared values and goals, and then presents the writer\'s position as compatible with those shared values, seeking a middle ground rather than demanding the audience abandon their views.'),
        q(38, 'An essay about the effects of social media on teen mental health is organized as follows: Paragraph 1 discusses anxiety, Paragraph 2 discusses depression, Paragraph 3 discusses sleep disruption, and Paragraph 4 discusses positive effects. Each paragraph follows the same internal pattern: research finding, expert analysis, real-world example. The organizational choice of consistent paragraph structure:', ['Is repetitive and should be varied', 'Creates coherence and predictability that helps readers follow complex information, while the parallel structure emphasizes the systematic nature of the analysis', 'Weakens the argument by being too formulaic', 'Is only appropriate for scientific writing'], 1, 'Consistent internal paragraph structure (sometimes called a "template" or "pattern") creates coherence across sections, making complex information easier to process. The parallel structure (research → analysis → example) signals thoroughness and methodical thinking, reinforcing the analytical ethos of the piece while making the argument accessible.'),
        q(39, 'In an argumentative essay, a writer strategically places their strongest counterargument and rebuttal immediately before the conclusion. This structural choice is effective because:', ['Counterarguments should always come at the end.', 'Addressing the strongest objection last demonstrates confidence, and the subsequent rebuttal leads naturally into a conclusion that feels definitive—the writer has overcome the toughest challenge to their thesis.', 'The conclusion is the least important part of the essay.', 'Readers skip the middle of essays.'], 1, 'Placing the strongest counterargument near the end creates a dramatic structure: the writer appears to face their most significant challenge head-on. Successfully rebutting it creates a sense of triumph that carries into the conclusion, making the thesis feel proven against the most formidable opposition. This structure also ensures the rebuttal is fresh in readers\' minds.'),
        q(40, 'A writer uses a concession phrase ("While it is true that...") followed by a pivot ("nevertheless...") multiple times throughout an essay. This pattern of concession and rebuttal serves the organizational function of:', ['Weakening the writer\'s argument through too many concessions', 'Systematically incorporating and responding to opposing viewpoints throughout the essay rather than isolating them in a single counterargument paragraph, creating a more nuanced and dialogic argument structure', 'Confusing the reader about the writer\'s position', 'Padding the essay to meet length requirements'], 1, 'Integrating concession-rebuttal patterns throughout the essay creates a dialogic structure that engages with opposition at every stage rather than in one isolated section. This organizational approach demonstrates that the writer\'s position can withstand scrutiny at each point, and it models the kind of nuanced thinking that characterizes sophisticated argumentation.'),
      ],
      hard: [
        q(41, 'A writer constructs an argument using the following structure: They open with a vivid narrative, transition to statistical evidence that contextualizes the narrative, present expert analysis, address counterarguments, and conclude with a return to the opening narrative from a new perspective. This structure achieves its rhetorical effect primarily through:', ['Simple chronological organization', 'A "frame" or "bookend" structure that uses the narrative to create emotional investment (pathos), supports it with logos in the middle, and returns to the narrative at the end to demonstrate how the evidence has transformed the reader\'s understanding of the opening story', 'Repetition that bores the reader', 'A strict five-paragraph essay format'], 1, 'The frame structure is a sophisticated organizational technique: the opening narrative creates emotional connection and raises questions. The evidence-based middle provides intellectual substance. Returning to the narrative at the end allows the reader to reinterpret it through the lens of the evidence presented, creating a satisfying sense of intellectual and emotional closure. The reader sees the same story differently—demonstrating the essay\'s argument experientially.'),
        q(42, 'An essayist arguing against a popular position begins not with their own thesis but with the strongest possible version of the opposing argument, presented sympathetically for three paragraphs, before pivoting to their own position. This strategy risks alienating readers who agree with the essayist but is employed because:', ['The writer is uncertain about their own position.', 'Steelmanning the opposition (presenting it in its strongest form before rebutting it) demonstrates that the writer understands the issue deeply, makes the subsequent rebuttal more impressive, and persuades skeptical readers that the writer has earned the right to disagree.', 'The writer wants to convince the opposition to switch sides.', 'Academic convention requires beginning with the opposing view.'], 1, 'Steelmanning (the opposite of strawmanning) presents the opposing argument at its strongest, most charitable interpretation. This builds extraordinary ethos: the writer demonstrates they understand the opposition better than its own advocates. When the pivot comes, the rebuttal is more persuasive because it overcomes the strongest version of the counterargument, not a weakened caricature. This is particularly effective for sophisticated audiences who would dismiss a straw man.'),
        q(43, 'A writer arguing for criminal justice reform uses a syllogism: "Policies that increase recidivism are counterproductive. Current mandatory minimum sentencing increases recidivism. Therefore, mandatory minimums are counterproductive." An opponent would most effectively challenge this argument by:', ['Questioning whether the conclusion follows logically from the premises.', 'Challenging the minor premise by presenting evidence that mandatory minimums do not actually increase recidivism, or challenging the major premise by arguing that deterrence effects justify policies even if they increase recidivism among those sentenced.', 'Attacking the writer\'s character and motives.', 'Arguing that all criminal justice policies are equally effective.'], 1, 'In deductive reasoning, the conclusion follows necessarily IF the premises are true. Effective challenges target the premises rather than the logical structure. Challenging the minor premise (disputing the evidence about recidivism) or the major premise (arguing that recidivism isn\'t the only relevant criterion, since deterrence matters too) undermines the argument without committing logical fallacies.'),
        q(44, 'An essay moves between personal narrative, historical analysis, scientific evidence, and philosophical reflection without clear transitions between these modes. Rather than following a linear argument, the essay circles back to earlier ideas with increasing complexity. This organization would be most appropriate for:', ['A standard academic research paper', 'A meditative or exploratory essay where the writer is thinking through a complex question and the organizational structure mirrors the process of deepening understanding', 'A persuasive speech to a hostile audience', 'A news article reporting facts'], 1, 'This recursive, associative structure characterizes the meditative essay tradition (Montaigne, Didion, Baldwin). Rather than driving toward a predetermined conclusion, it models the writer\'s evolving understanding. Each return to an earlier idea adds new layers of meaning. This structure is appropriate when the subject resists simple linear treatment and the writer\'s thinking process is itself part of the argument.'),
        q(45, 'A writer constructs a causal argument claiming that policy X led to outcome Y. A rhetorical analyst identifies that the writer has committed the "post hoc ergo propter hoc" fallacy. However, the analyst notes that the writer has also provided a plausible mechanism connecting X to Y and has controlled for alternative explanations. The analyst should conclude that:', ['The argument is entirely fallacious and should be rejected.', 'While the temporal sequence alone would be fallacious, the addition of a plausible causal mechanism and elimination of alternative explanations transforms the argument from fallacious reasoning into a legitimate causal claim supported by multiple forms of evidence.', 'Post hoc reasoning is always valid when accompanied by any additional evidence.', 'The analyst should ignore the fallacy if they agree with the conclusion.'], 1, 'This illustrates a nuanced understanding of logical reasoning. The post hoc fallacy occurs when temporal sequence alone is treated as proof of causation. However, establishing a causal mechanism (explaining HOW X causes Y) and controlling for confounders (ruling out alternative explanations) builds a legitimate causal argument. The temporal relationship becomes one piece of evidence within a larger argumentative framework, not the sole basis for the claim.'),
      ],
    },
    {
      unitNumber: 4,
      title: 'Style',
      easy: [
        q(46, 'The "tone" of a written work refers to:', ['The volume at which the text should be read aloud', 'The writer\'s attitude toward the subject or audience as conveyed through word choice, sentence structure, and rhetorical strategies', 'The genre of the writing', 'The number of paragraphs in the essay'], 1, 'Tone is the writer\'s attitude toward the subject and/or audience, communicated through diction (word choice), syntax (sentence structure), imagery, and other stylistic elements. Tone can be formal, informal, earnest, ironic, urgent, contemplative, humorous, or any other attitudinal quality.'),
        q(47, 'Diction refers to a writer\'s:', ['Use of punctuation', 'Choice of words and the connotations those words carry', 'Paragraph organization', 'Use of quotations from other sources'], 1, 'Diction is the writer\'s deliberate selection of words. It encompasses denotation (literal meaning) and connotation (associated feelings and implications). Choosing "home" versus "house" versus "residence" versus "dwelling" conveys different tones and relationships to the subject.'),
        q(48, 'A writer uses short, declarative sentences in succession: "He walked in. He sat down. He said nothing." This syntactical choice creates:', ['A sense of confusion for the reader', 'A clipped, tense, or dramatic effect that emphasizes each action and suggests emotional restraint or intensity', 'An academic and formal tone', 'A sense of relaxation and ease'], 1, 'Short, declarative sentences create a staccato rhythm that conveys tension, urgency, or emotional restraint. Each sentence stands as its own unit, drawing attention to individual actions and creating a sense of deliberateness or controlled intensity.'),
        q(49, 'A metaphor is a figure of speech that:', ['Compares two things using "like" or "as"', 'Directly identifies one thing as another, creating an implicit comparison', 'Exaggerates for emphasis', 'Addresses an absent person or abstract concept'], 1, 'A metaphor creates a direct comparison by stating that one thing IS another: "Time is money" or "The world is a stage." Unlike a simile (which uses "like" or "as"), a metaphor asserts identity between the two concepts, creating a more forceful and integrated comparison.'),
        q(50, 'An author who uses formal academic language, complex sentence structures, and specialized terminology is writing for:', ['A general audience of casual readers', 'An educated, specialized audience familiar with the subject matter and discourse conventions', 'Children and young adults', 'An audience that prefers simple, direct communication'], 1, 'Formal academic language, complex syntax, and specialized vocabulary signal an audience with advanced education, subject-matter knowledge, and familiarity with academic discourse conventions. This stylistic register assumes shared knowledge and values precise, nuanced expression over accessibility.'),
      ],
      medium: [
        q(51, 'A writer describes a corporation\'s environmental damage using words like "ravaged," "plundered," and "devastated" instead of "damaged," "used," and "affected." This diction choice reflects:', ['Neutral, objective reporting', 'Deliberately loaded language that shapes the reader\'s emotional response by assigning violent, aggressive connotations to the corporation\'s actions, strengthening the writer\'s critical stance', 'Poor vocabulary skills', 'The writer\'s attempt to be scientifically accurate'], 1, 'The writer\'s choice of emotionally charged, violent diction ("ravaged," "plundered," "devastated") transforms a description of environmental damage into an implicit moral argument. These words carry connotations of violence, greed, and destruction that shape the reader\'s emotional response and moral judgment before any explicit argument is made. This illustrates how diction functions as a persuasive tool.'),
        q(52, 'Parallel structure (parallelism) in writing involves:', ['Repeating the same idea multiple times', 'Using grammatically similar constructions for related ideas, creating rhythm, emphasis, and clarity', 'Writing in the second person throughout an essay', 'Alternating between long and short paragraphs'], 1, 'Parallelism uses the same grammatical form for items in a series, paired ideas, or contrasted elements: "government of the people, by the people, for the people." Parallel structure creates rhythmic balance, makes ideas memorable, emphasizes their equal importance, and clarifies the logical relationship between concepts.'),
        q(53, 'A writer alternates between long, complex sentences with multiple subordinate clauses and short, punchy sentences. This syntactical variety achieves:', ['Inconsistency that confuses readers', 'Rhythmic variation that maintains reader engagement, with long sentences building complexity and short sentences delivering emphasis or surprise', 'Nothing—sentence length doesn\'t affect meaning', 'A purely aesthetic effect with no rhetorical purpose'], 1, 'Syntactical variety creates a rhythm that mirrors the content\'s emphasis. Long sentences can build suspense, convey complexity, or create a sense of accumulation. A short sentence following a long one creates emphasis through contrast—the reader\'s attention is drawn to the concise statement. This variation keeps prose dynamic and directs reader attention strategically.'),
        q(54, 'Irony in writing occurs when:', ['The writer says exactly what they mean', 'There is a discrepancy between what is said and what is meant, between expectation and reality, or between appearance and truth', 'The writer uses humor to entertain the reader', 'The writer employs formal language exclusively'], 1, 'Irony involves a gap between surface meaning and intended meaning (verbal irony), between expected and actual outcomes (situational irony), or between what a character knows and what the audience knows (dramatic irony). In rhetoric, irony can create humor, convey criticism, or invite the audience to see beyond appearances.'),
        q(55, 'An author employs an extended metaphor throughout an entire essay, comparing the American education system to an assembly line. This stylistic choice:', ['Limits the essay\'s scope to only manufacturing topics', 'Provides a unifying conceptual framework that shapes how readers understand every aspect of the education system discussed, influencing their interpretation through the implications of the metaphor', 'Is merely decorative and adds no meaning', 'Makes the essay harder to understand for all readers'], 1, 'An extended metaphor structures the reader\'s entire conceptual framework. Comparing education to an assembly line implies standardization, mass production, treating students as products, efficiency over individuality, and workers (teachers) performing repetitive tasks. Every detail of the essay is filtered through this metaphor, shaping interpretation even of facts that might be read differently without it. The metaphor does significant argumentative work beyond decoration.'),
      ],
      hard: [
        q(56, 'A writer crafting a sentence about a government bureaucracy deliberately uses convoluted syntax, excessive subordinate clauses, and passive constructions: "The forms, which had been submitted by the applicants who had been waiting, were said to have been processed by the office that had been designated for such purposes." The style itself becomes:', ['Poor writing that should be edited for clarity', 'A mimetic stylistic choice where the sentence\'s complexity and opacity mirror the bureaucratic processes being described, making form reflect content', 'A demonstration of the writer\'s grammatical sophistication', 'An accident resulting from insufficient revision'], 1, 'This is mimetic style—where the form of the writing imitates its content. The sentence\'s bureaucratic complexity, passive constructions, and layers of subordination enact the frustrating opacity of bureaucratic processes. The reader\'s experience of struggling through the sentence mirrors the subject\'s experience of navigating bureaucracy. When form mirrors content, style becomes an argumentative tool.'),
        q(57, 'Two writers address the same topic—income inequality. Writer A uses abstract, academic language ("socioeconomic stratification," "distributional asymmetries"). Writer B uses concrete, visceral language ("a mother choosing between medicine and groceries," "rusted playgrounds beside gleaming office towers"). These stylistic differences reveal:', ['That Writer A is correct and Writer B is emotional', 'Different rhetorical strategies: Writer A creates intellectual distance and claims scholarly objectivity, while Writer B creates emotional proximity and moral urgency; each style positions the reader differently in relation to the issue and implies different responses.', 'That Writer B is a better writer overall', 'Nothing meaningful—both say the same thing in different words'], 1, 'These stylistic differences are not just cosmetic—they constitute different arguments about how the reader should relate to inequality. Abstract language creates intellectual distance, framing inequality as a systemic phenomenon to be analyzed. Concrete, specific imagery creates emotional proximity, framing inequality as a moral crisis demanding immediate human response. Each style implies different kinds of engagement and different solutions.'),
        q(58, 'A writer begins an essay about loss with the sentence: "My mother is alive." The simple, declarative sentence contradicts the reader\'s expectation for an essay about loss. This opening achieves its effect through:', ['Misleading the reader about the essay\'s topic', 'Strategic violation of reader expectations that creates tension, invites curiosity about what kind of loss the essay explores (emotional distance? dementia? estrangement?), and demonstrates that style—particularly when it disrupts conventions—generates meaning through what it withholds as much as what it states', 'A grammatical error that should be corrected', 'Avoiding the essay\'s actual subject'], 1, 'This opening uses understatement and expectation violation as sophisticated stylistic tools. The simple sentence\'s stark declarativeness against the essay\'s topic of loss creates cognitive dissonance that hooks the reader: what kind of loss are we exploring? The restraint generates meaning through implication—what isn\'t said (the specific nature of the loss) becomes more powerful than what is said, demonstrating that style operates through absence and suggestion as much as through statement.'),
        q(59, 'A rhetorical analyst notices that a writer consistently uses the passive voice when describing corporate actions ("mistakes were made," "chemicals were released") but active voice when describing community responses ("residents organized," "parents demanded answers"). This syntactical pattern:', ['Is an inconsistency the writer should correct', 'Is a deliberate rhetorical choice that obscures corporate agency and responsibility (passive voice removes the actor) while emphasizing community agency and action, thereby shaping the moral landscape of the narrative', 'Has no rhetorical significance', 'Follows standard grammatical conventions'], 1, 'This selective use of voice is a sophisticated rhetorical strategy. Passive constructions for corporate actions ("chemicals were released") remove the agent, linguistically enacting the evasion of responsibility the writer is likely critiquing. Active constructions for community responses ("residents organized") emphasize human agency and moral authority. The syntactical pattern itself embodies the argument about power and accountability.'),
        q(60, 'An essayist\'s prose style evolves within a single essay from controlled, measured sentences in the opening to increasingly fragmented, breathless syntax as the argument reaches its emotional climax, before returning to calm, reflective prose in the conclusion. This stylistic arc:', ['Indicates the writer lost control of their prose during the emotional section', 'Functions as a structural and emotional device: the stylistic progression mirrors the intellectual and emotional journey the writer wants the reader to experience, with syntax performing the argument\'s emotional trajectory rather than merely describing it', 'Should be eliminated through careful revision for consistency', 'Is only effective in fiction, not in argumentative essays'], 1, 'This progressive stylistic modulation is a hallmark of literary nonfiction at its most sophisticated. The syntax doesn\'t just convey information—it performs the argument\'s emotional arc. Controlled opening prose establishes authority, fragmenting syntax enacts the urgency or anguish of the central argument, and the return to measured prose models resolution. The reader\'s physiological response to the prose rhythm (faster reading during fragments, slower during complex sentences) creates an embodied experience of the argument.'),
      ],
    },
  ],
}
